function validate([n, roads, appleCost, k]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n is between 2 and 1000.';
  if (!Array.isArray(roads) || roads.length < 1 || roads.length > 1000) return 'roads needs 1 to 1000 entries.';
  const seen = new Set();
  for (const road of roads) {
    if (!Array.isArray(road) || road.length !== 3) return 'Each road is [a, b, cost].';
    const [a, b, cost] = road;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || b < 1 || a > n || b > n) return 'Road ends are cities 1 to n.';
    if (a === b) return 'A road joins two different cities.';
    if (!Number.isInteger(cost) || cost < 1 || cost > 100000) return 'Each road cost is between 1 and 10^5.';
    const key = Math.min(a, b) * 2000 + Math.max(a, b);
    if (seen.has(key)) return 'Two roads join the same pair of cities.';
    seen.add(key);
  }
  if (!Array.isArray(appleCost) || appleCost.length !== n) return 'appleCost needs exactly n values.';
  if (appleCost.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each apple cost is between 1 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is between 1 and 100.';
  return null;
}

