function minCost(n, roads, appleCost, k) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b, cost] of roads) {
    graph[a - 1].push([b - 1, cost * (k + 1)]);
    graph[b - 1].push([a - 1, cost * (k + 1)]);
  }
  const dist = appleCost.slice();
  const heap = [];
  const push = (total, city) => {
    heap.push([total, city]);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === i) break;
        [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
        i = smallest;
      }
    }
    return top;
  };
  for (let city = 0; city < n; city++) push(dist[city], city);
  while (heap.length > 0) {
    const [total, city] = pop();
    if (total > dist[city]) continue;
    for (const [next, weight] of graph[city]) {
      if (total + weight < dist[next]) {
        dist[next] = total + weight;
        push(dist[next], next);
      }
    }
  }
  return dist;
}

