function minCost(n, roads, appleCost, k) {
  // Floyd-Warshall for plain road distances, then try every shop from every start.
  const d = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 0 : Infinity)));
  for (const [a, b, c] of roads) {
    d[a - 1][b - 1] = Math.min(d[a - 1][b - 1], c);
    d[b - 1][a - 1] = Math.min(d[b - 1][a - 1], c);
  }
  for (let m = 0; m < n; m++)
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (d[i][m] + d[m][j] < d[i][j]) d[i][j] = d[i][m] + d[m][j];
  const answer = [];
  for (let i = 0; i < n; i++) {
    let best = Infinity;
    for (let j = 0; j < n; j++) {
      if (d[i][j] === Infinity) continue;
      best = Math.min(best, d[i][j] + appleCost[j] + d[j][i] * k);
    }
    answer.push(best);
  }
  return answer;
}

