function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(900, 1000) : int(2, 7);
  const maxPairs = (n * (n - 1)) / 2;
  const chain = large && rand() < 0.4;
  const roadCount = chain ? n - 1 : large ? int(800, 1000) : int(1, Math.min(maxPairs, 10));
  const costHi = large ? 100000 : rand() < 0.2 ? 100000 : 10;
  const appleHi = large ? 100000 : rand() < 0.2 ? 100000 : 60;
  const used = new Set();
  const roads = [];
  if (chain) {
    const order = Array.from({ length: n }, (_, i) => i + 1);
    for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
    for (let i = 0; i + 1 < n; i++) roads.push([order[i], order[i + 1], int(1, costHi)]);
  } else {
    while (roads.length < roadCount) {
      const a = int(1, n), b = int(1, n);
      if (a === b) continue;
      const key = Math.min(a, b) * 2000 + Math.max(a, b);
      if (used.has(key)) continue;
      used.add(key);
      roads.push([a, b, int(1, costHi)]);
    }
  }
  const appleCost = Array.from({ length: n }, () => int(1, appleHi));
  const k = large ? (rand() < 0.5 ? 100 : int(1, 100)) : rand() < 0.15 ? 100 : int(1, 4);
  return [n, roads, appleCost, k];
}
